import net.minecraft.entity.player.EntityPlayerMP; import net.minecraft.item.Item; import net.minecraft.item.ItemStack; import net.minecraft.util.ResourceLocation; import net.minecraftforge.fluids.FluidRegistry; import net.minecraftforge.fluids.FluidStack; import com.rtsbuilding.rtsbuilding.platform.storage.IFluidHandler; import com.rtsbuilding.rtsbuilding.platform.storage.IFluidTankProperties; import com.rtsbuilding.rtsbuilding.platform.registry.RtsRegistries; import com.rtsbuilding.rtsbuilding.platform.storage.IItemHandler;
