public final class RtsPageCore {
 private RtsPageCore(){}
 public static void clearCache(UUID id){RtsPageCache.INSTANCE.remove(id);}
 public static PageResult build(EntityPlayerMP player,RtsStorageSession session,int requestedPage,int requestedSize,List<LinkedHandler> active,List<LinkedFluidHandler> activeFluids){
  List<LinkedHandler> handlers=active==null?Collections.<LinkedHandler>emptyList():active;List<LinkedFluidHandler> fluids=activeFluids==null?Collections.<LinkedFluidHandler>emptyList():activeFluids;boolean includeInventory=RtsPageSharedHelpers.shouldIncludePlayerMainInventoryInStorageView(player,session);LinkedRefPayload refs=RtsPagePayloadFactory.buildLinkedRefPayload(player,session);
  if(session.linkedStorageInfo.isEmpty()&&handlers.isEmpty()&&fluids.isEmpty()&&!hasPositiveInternalFluid(session)&&!includeInventory)return new PageResult(RtsPagePayloadFactory.buildEmpty(player,session),0);
  int pageSize=RtsPageSharedHelpers.sanitizePageSize(requestedSize);RtsPageCache.CachedPageKey key=new RtsPageCache.CachedPageKey(session.browser.search,session.browser.sort,session.browser.category,session.browser.ascending,pageSize,session.browser.pinyinSearchEnabled,includeInventory);RtsPageCache.CachedPage cached=RtsPageCache.INSTANCE.get(player.getUniqueID());
  Map<String,Long> counts,namespaceTotals;List<String>categories;List<Entry>entries;List<FluidEntry>fluidEntries;boolean hit=cached!=null&&cached.key().equals(key)&&cached.dataVersion()==session.transfer.pageDataVersion.get();
  if(hit){counts=cached.counts();namespaceTotals=cached.namespaceTotals();categories=cached.categories();entries=cached.sortedEntries();fluidEntries=cached.sortedFluidEntries();}
  else{
   RtsDeveloperMetrics.recordPageBuild(player);counts=new LinkedHashMap<String,Long>();namespaceTotals=new HashMap<String,Long>();List<Entry>exact=new ArrayList<Entry>();
   /* Aggregate cache is item-id keyed and cannot represent metadata/NBT variants; page construction scans real handlers. */
   for(LinkedHandler linked:handlers){IItemHandler h=linked==null?null:linked.handler();if(h==null)continue;for(int slot=0;slot<h.getSlots();slot++){ItemStack stack=h.getStackInSlot(slot);if(stack==null||com.rtsbuilding.rtsbuilding.platform.storage.StackCompat.isEmpty(stack))continue;ResourceLocation id=RtsRegistries.ITEMS.getKey(stack.getItem());if(id==null)continue;long amount=getHandlerReportedCount(h,slot,stack);mergeCount(counts,id.toString(),amount);mergeCount(namespaceTotals,id.getResourceDomain(),amount);mergeExactEntry(exact,stack,amount);}}
   if(includeInventory){accumulatePlayerMainInventoryCounts(player,counts,namespaceTotals);accumulatePlayerMainInventoryEntries(player,exact);}
   Map<String,Long> fluidAmounts=new HashMap<String,Long>(),fluidCaps=new HashMap<String,Long>();for(Map.Entry<String,Long> e:session.sessionFlags.internalFluidMb.entrySet())if(e.getValue()!=null&&e.getValue()>0)mergeCount(fluidAmounts,e.getKey(),e.getValue());
   for(LinkedFluidHandler linked:fluids){IFluidHandler h=linked==null?null:linked.handler();if(h==null)continue;IFluidTankProperties[] tanks=h.getTankProperties();if(tanks==null)continue;for(IFluidTankProperties tank:tanks){if(tank==null)continue;FluidStack f=tank.getContents();if(f==null||f.amount<=0||f.getFluid()==null)continue;String id=FluidRegistry.getFluidName(f);if(id==null)continue;mergeCount(fluidAmounts,id,f.amount);mergeCount(fluidCaps,id,Math.max(0,tank.getCapacity()));}}
   long internalCap=RtsStorageFluids.internalFluidCapacityMb(player);for(String id:fluidAmounts.keySet()){mergeCount(fluidCaps,id,internalCap);ResourceLocation rl=RtsPageSharedHelpers.parse(id);if(rl!=null)mergeCount(namespaceTotals,rl.getResourceDomain(),fluidAmounts.get(id));}
   Map<String,Set<String>>itemTabs=new HashMap<String,Set<String>>(),modTabs=new HashMap<String,Set<String>>();if(!counts.isEmpty()&&RtsPageCreativeTabIndexer.ensureCreativeTabContents(player))RtsPageCreativeTabIndexer.buildItemTabMapping(counts,itemTabs,modTabs,com.rtsbuilding.rtsbuilding.platform.player.PlayerCompat.canUseCommand(player, 2,""));
   List<String>namespaces=new ArrayList<String>(namespaceTotals.keySet());Collections.sort(namespaces,new Comparator<String>(){public int compare(String a,String b){return RtsPageSharedHelpers.compareNamespace(a,b);}});categories=new ArrayList<String>();categories.add(RtsPageSharedHelpers.CATEGORY_ALL);for(String ns:namespaces){categories.add(RtsPageSharedHelpers.encodeModCategory(ns));List<String>tabs=new ArrayList<String>(modTabs.containsKey(ns)?modTabs.get(ns):Collections.<String>emptySet());Collections.sort(tabs,new Comparator<String>(){public int compare(String a,String b){return RtsPageSharedHelpers.compareTabKey(a,b);}});for(String tab:tabs)categories.add(RtsPageSharedHelpers.encodeTabCategory(ns,tab));}
   CategorySelection selected=RtsPageSharedHelpers.parseCategorySelection(session.browser.category);if(!RtsPageSharedHelpers.isValidCategorySelection(selected,categories)){session.browser.category=RtsPageSharedHelpers.CATEGORY_ALL;selected=CategorySelection.all();}
   String query=session.browser.search==null?"":session.browser.search.toLowerCase(Locale.ROOT).trim();entries=new ArrayList<Entry>();for(Entry e:exact){ResourceLocation id=RtsPageSharedHelpers.parse(e.itemId());if(!RtsPageSharedHelpers.matchesSearchQuery(id,e.itemId(),e.label(),query,session.browser.pinyinSearchEnabled,session.browser.localizedSearchMatches))continue;Set<String>tabs=itemTabs.containsKey(e.itemId())?itemTabs.get(e.itemId()):Collections.<String>emptySet();if(selected.matches(e.namespace(),tabs))entries.add(e);}
   fluidEntries=new ArrayList<FluidEntry>();for(Map.Entry<String,Long> e:fluidAmounts.entrySet()){ResourceLocation id=RtsPageSharedHelpers.parse(e.getKey());if(!RtsPageSharedHelpers.matchesSearchQuery(id,e.getKey(),null,query,session.browser.pinyinSearchEnabled,session.browser.localizedSearchMatches))continue;String ns=id==null?"unknown":id.getResourceDomain();if(selected.isCreativeTab()||!selected.matches(ns,Collections.<String>emptySet()))continue;long amount=Math.max(0,e.getValue());long cap=Math.max(amount,fluidCaps.containsKey(e.getKey())?fluidCaps.get(e.getKey()):internalCap);fluidEntries.add(new FluidEntry(e.getKey(),ns,id==null?e.getKey():id.getResourcePath(),amount,cap));}
   Collections.sort(entries,RtsPageSharedHelpers.entryComparator(session.browser.sort,session.browser.ascending));Collections.sort(fluidEntries,RtsPageSharedHelpers.fluidComparator(session.browser.sort,session.browser.ascending));RtsPageCache.INSTANCE.put(player.getUniqueID(),new RtsPageCache.CachedPage(key,session.transfer.pageDataVersion.get(),entries,fluidEntries,counts,namespaceTotals,categories));
  }
  int total=entries.size(),pages=Math.max(1,(total+pageSize-1)/pageSize),safe=Math.max(0,Math.min(requestedPage,pages-1)),from=safe*pageSize,to=Math.min(from+pageSize,total);List<ItemStack>pageStacks=new ArrayList<ItemStack>();List<Long>pageCounts=new ArrayList<Long>();for(int i=from;i<to;i++){Entry e=entries.get(i);pageStacks.add(e.stack().copy());pageCounts.add(e.count());}
  boolean snapshot=shouldSendTotalCountsSnapshot(session.browser.search);List<String>totalIds=snapshot?new ArrayList<String>():Collections.<String>emptyList();List<Long>totalCounts=snapshot?new ArrayList<Long>():Collections.<Long>emptyList();if(snapshot)for(Map.Entry<String,Long>e:counts.entrySet()){totalIds.add(e.getKey());totalCounts.add(e.getValue());}
  List<String>fluidIds=new ArrayList<String>();List<Long>fluidAmounts=new ArrayList<Long>(),fluidCaps=new ArrayList<Long>();for(FluidEntry e:fluidEntries){fluidIds.add(e.fluidId());fluidAmounts.add(e.amount());fluidCaps.add(e.capacity());}
  List<String>recentIds=new ArrayList<String>();List<Long>recentAmounts=new ArrayList<Long>(),recentCaps=new ArrayList<Long>();List<Byte>recentKinds=new ArrayList<Byte>();for(com.rtsbuilding.rtsbuilding.server.storage.model.RecentEntry recent:session.uiMemory.getRecentEntries()){recentIds.add(recent.id());recentAmounts.add(recent.amount());recentCaps.add(recent.capacity());recentKinds.add(recent.kind());}
  Map<String,Long>funnel=RtsPagePayloadFactory.summarizeFunnelBuffer(session);List<String>funnelIds=new ArrayList<String>(funnel.keySet());List<Long>funnelCounts=new ArrayList<Long>(funnel.values());int q=RtsStorageBindings.QUICK_SLOT_COUNT,g=RtsStorageBindings.GUI_BINDING_SLOT_COUNT;
  return new PageResult(new S2CRtsStoragePagePayload(RtsLinkedStorageResolver.hasAnyStorage(player,session),RtsLinkedStorageResolver.buildAnyStorageSummary(player,session),refs.positions(),refs.names(),refs.modes(),refs.priorities(),refs.iconItemIds(),refs.worldAvailable(),safe,pages,total,snapshot,session.browser.search,session.browser.category,(byte)session.browser.sort.ordinal(),session.browser.ascending,session.sessionFlags.autoStoreMinedDrops,session.sessionFlags.useBdNetwork,categories,pageStacks,pageCounts,totalIds,totalCounts,fluidIds,fluidAmounts,fluidCaps,recentIds,recentAmounts,recentCaps,recentKinds,RtsStorageUiPayloads.buildQuickSlotPayload(session,q),RtsStorageUiPayloads.buildQuickSlotPreviewPayload(session,q),RtsStorageUiPayloads.buildGuiBindingLabelPayload(session,g),RtsStorageUiPayloads.buildGuiBindingItemIdPayload(session,g),session.funnel.funnelEnabled,funnelIds,funnelCounts),safe);
 }
 static boolean shouldSendTotalCountsSnapshot(String search){return search==null||search.trim().isEmpty();}
 public static long getHandlerReportedCount(IItemHandler h,int slot,ItemStack stack){return sanitizeCount(RtsAe2Compat.getReportedCount(h,slot,stack));}
 static void mergeCount(Map<String,Long>m,String key,long amount){if(m==null||key==null||key.trim().isEmpty())return;long value=sanitizeCount(amount);if(value<=0)return;Long old=m.get(key);m.put(key,saturatedAdd(old==null?0:old,value));}
 public static long saturatedAdd(long a,long b){long x=sanitizeCount(a),y=sanitizeCount(b);return x==Long.MAX_VALUE||y==Long.MAX_VALUE||Long.MAX_VALUE-x<y?Long.MAX_VALUE:x+y;} public static long sanitizeCount(long v){return v<=0?0:v;}
 public static void accumulatePlayerMainInventoryCounts(EntityPlayerMP player,Map<String,Long>counts,Map<String,Long>ns){if(player==null)return;for(int slot=RtsPageSharedHelpers.getPlayerMainInventoryStart(player);slot<RtsPageSharedHelpers.getPlayerMainInventoryEndExclusive(player);slot++){ItemStack stack=player.inventory.getStackInSlot(slot);if(com.rtsbuilding.rtsbuilding.platform.storage.StackCompat.isEmpty(stack))continue;ResourceLocation id=RtsRegistries.ITEMS.getKey(stack.getItem());if(id!=null){mergeCount(counts,id.toString(),stack.stackSize);mergeCount(ns,id.getResourceDomain(),stack.stackSize);}}}
 static void accumulatePlayerMainInventoryEntries(EntityPlayerMP player,List<Entry>entries){if(player==null)return;for(int slot=RtsPageSharedHelpers.getPlayerMainInventoryStart(player);slot<RtsPageSharedHelpers.getPlayerMainInventoryEndExclusive(player);slot++){ItemStack stack=player.inventory.getStackInSlot(slot);if(!com.rtsbuilding.rtsbuilding.platform.storage.StackCompat.isEmpty(stack))mergeExactEntry(entries,stack,stack.stackSize);}}
 static void mergeExactEntry(List<Entry>entries,ItemStack stack,long count){if(entries==null||stack==null||com.rtsbuilding.rtsbuilding.platform.storage.StackCompat.isEmpty(stack)||count<=0)return;ResourceLocation id=RtsRegistries.ITEMS.getKey(stack.getItem());if(id==null)return;ItemStack prototype=stack.copy();prototype.stackSize = 1;for(int i=0;i<entries.size();i++){Entry old=entries.get(i);if(!sameStack(old.stack(),prototype))continue;entries.set(i,new Entry(old.stack(),old.itemId(),old.namespace(),old.path(),old.label(),saturatedAdd(old.count(),count)));return;}entries.add(new Entry(prototype,id.toString(),id.getResourceDomain(),id.getResourcePath(),prototype.getDisplayName(),count));}
 static boolean sameStack(ItemStack a,ItemStack b){return com.rtsbuilding.rtsbuilding.platform.storage.StackCompat.areItemsEqual(a,b)&&ItemStack.areItemStackTagsEqual(a,b);} private static boolean hasPositiveInternalFluid(RtsStorageSession s){if(s==null)return false;for(Long v:s.sessionFlags.internalFluidMb.values())if(v!=null&&v>0)return true;return false;}
}
